update catatan_surveyor set hal_baik = '{"Halaman depan ada pohon mangga rindang, sore hari adem.","Kunci kamar ganda, pemilik tidak pegang duplikat tanpa izin.","Ada CCTV di gerbang dan koridor tiap lantai."}'::text[], perlu_diketahui = '{"Motor parkir di gang depan, tidak beratap.","Tamu hanya boleh sampai ruang tamu, tidak boleh masuk kamar.","Kamar mandi luar dipakai bersama untuk tipe Standar dan Kamar besar (3×4 m)."}'::text[], kesan_pemilik = 'Agak sulit dihubungi siang hari, balas WhatsApp malam.', red_flags = '{"Sebagian kamar tidak punya jendela ke luar; ventilasi hanya ke koridor."}'::text[] where kos_id = '9ea2b810-3ac7-4521-af97-149b641b3b6e';
update catatan_surveyor set hal_baik = '{"Halaman depan ada pohon mangga rindang, sore hari adem.","Kasur dan lemari masih baru, diganti awal 2026.","Gang cukup lebar, mobil bisa masuk sampai depan kos."}'::text[], perlu_diketahui = '{"Listrik meteran; pemilik belum bisa menyebut rata-rata tagihan, jadi total di sini belum termasuk listrik.","Sinyal Telkomsel lemah di kamar belakang, XL aman.","Air kadang keruh setelah hujan deras, pemilik bilang sedang pasang filter."}'::text[], kesan_pemilik = 'Dikelola anak pemilik, cepat tanggap soal kerusakan.', red_flags = '{}'::text[] where kos_id = 'ac2ad299-5308-460a-a9e5-d529ab1289b4';
